def load():
    """MNID -> (名字, 等级下限, 等级上限, 称号, 是否任务NPC)"""
    global _DB
    if _DB is not None:
        return _DB
    d = {}
    txt = _zlib.decompress(_b64.b64decode(_RAW_ROWS)).decode("utf-8")
    for rec in txt.split("|"):
        if not rec:
            continue
        p = rec.split(":")
        if len(p) != 6:
            continue
        d[int(p[0])] = (NAMES[int(p[1])], int(p[2]), int(p[3]),
                        TITLES[int(p[4])], p[5] == "1")
    _DB = d
    return d
